$content = Get-Content "app/src/main/java/com/attendance/app/student/ui/StudentClassDetailScreen.kt" -Raw
$content = $content -replace "(?m)^(\s*val todayStatus by attendanceViewModel.todayStatus.collectAsState\(\))", "`$1`n    val attendanceAction by attendanceViewModel.attendanceAction.collectAsState()`n`n    androidx.compose.runtime.LaunchedEffect(attendanceAction) {`n        when (val action = attendanceAction) {`n            is com.attendance.app.student.presentation.AttendanceAction.RequireFaceVerification -> {`n                navController.navigate(com.attendance.app.core.ui.navigation.Screen.FaceVerification(action.classId))`n                attendanceViewModel.resetAction()`n            }`n            else -> {}`n        }`n    }"
Set-Content "app/src/main/java/com/attendance/app/student/ui/StudentClassDetailScreen.kt" $content
